using BenchmarkDotNet.Attributes;
using Microsoft.Data.Sqlite;
using Microsoft.EntityFrameworkCore;
using OptimizingEfCoreQueries.Shared;
using OptimizingEfCoreQueries.Scenarios;

namespace OptimizingEfCoreQueries.Benchmarks;

// Baseline materializes full Product entities (heavy Description/Thumbnail
// columns) then maps; Optimized calls the agent-owned ProjectionSolution.Run.
// Do not edit this file — edit Scenarios/Projection.cs.
[Config(typeof(SharedBenchmarkConfig))]
public class ProjectionBenchmark
{
    private const int CategoryId = 3;
    private SqliteConnection _connection = null!;

    [GlobalSetup]
    public void Setup()
    {
        _connection = AppDbContext.OpenSharedConnection();
        using var db = AppDbContext.Create(_connection);
        db.Database.EnsureCreated();
        SeedData.SeedProducts(db, products: 20000, categories: 10, descriptionChars: 2000, thumbnailBytes: 4096);

        EquivalenceGuard.SameResults(Baseline(), Optimized(), p => p.Id.ToString());
    }

    [GlobalCleanup]
    public void Cleanup() => _connection.Dispose();

    [Benchmark(Baseline = true)]
    public List<ProductListItem> Baseline()
    {
        using var db = AppDbContext.Create(_connection);
        var products = db.Products.Where(p => p.CategoryId == CategoryId).ToList();
        return products.Select(p => new ProductListItem(p.Id, p.Name, p.Price)).ToList();
    }

    [Benchmark]
    public List<ProductListItem> Optimized()
    {
        using var db = AppDbContext.Create(_connection);
        return ProjectionSolution.Run(db, CategoryId);
    }
}
